    SELECT CAST(value AS REAL)
    FROM shop_meta
    WHERE key = 'minor_units_per_dollar'
), 2) AS average_refund_dollars
FROM refunds;

SELECT MAX(DATE(delivered_at)) AS most_recent_delivery_date
FROM orders
WHERE status = 'delivered_complete';

SELECT name
FROM products
WHERE price_minor = (SELECT MIN(price_minor) FROM products);

SELECT country, COUNT(*) AS customer_count
FROM customers
GROUP BY country;

SELECT ROUND(100.0 * COUNT(CASE WHEN order_id IS NULL THEN 1 END)
             / NULLIF(COUNT(*), 0), 2) AS percentage
FROM tickets;

SELECT COALESCE(SUM(
    o.shipping_minor + COALESCE((
        SELECT SUM(oi.quantity * oi.unit_price_minor)
        FROM order_items AS oi
        WHERE oi.order_id = o.id
    ), 0)
), 0) / (
    SELECT CAST(value AS REAL)
    FROM shop_meta
    WHERE key = 'minor_units_per_dollar'
) AS total_charge_dollars
FROM orders AS o
WHERE o.status = 'pending_payment';

